contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amt, uint fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amt > 0);
        require(fund > amt);
        require(address(this).balance >= fund);
        // Fund C: this contract is C's owner and is payable, so C can send to us.
        c.sendTo(address(this), fund); if (__ESBMC_reverted()) return;
        uint before = address(c).balance;
        require(before >= fund);
        // Partial transfer (amt < balance) to a payable receiver must succeed.
        c.sendTo(address(this), amt); if (__ESBMC_reverted()) return;
        assert(address(c).balance == before - amt && address(c).balance > 0);
    }
    receive() external payable {}
}

