// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 amt, uint256 fund) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt > 0);
        vm.assume(fund > amt);
        vm.assume(address(this).balance >= fund);
        try c.sendTo(address(this), fund) {} catch { return; }
        uint before = address(c).balance;
        vm.assume(before >= fund);
        try c.sendTo(address(this), amt) {} catch { return; }
        assertTrue(address(c).balance == before - amt && address(c).balance > 0);
    }

    function testFuzz_run(uint256 amt, uint256 fund) public {
        _run(amt, fund);
    }

    receive() external payable {}
}
